/bin/zsh -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { importStock } from './src/entry.js';

const output = importStock(' ab-2 ,5,8');
assert.deepEqual(output, { product_code: 'AB-2', units: 0, schema: 2 });
let invalidNumeric;
try {
  importStock('x,no,1');
  assert.fail('Expected an invalid count error');
} catch (error) {
  invalidNumeric = error.message;
}
assert.equal(invalidNumeric, 'invalid count');
assert.deepEqual(importStock('x,-3,-2'), { product_code: 'X', units: 0, schema: 2 });
assert.deepEqual(importStock('x,5,2'), { product_code: 'X', units: 3, schema: 2 });
process.stdout.write(JSON.stringify({ status: 'passed', output, invalid_numeric: invalidNumeric, negative_availability_units: 0, positive_after_reservation_units: 3 }) + '\\n');
NODE"

