/bin/zsh -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { readFile, writeFile } from 'node:fs/promises';
import { importStock } from './src/entry.js';

let invalidNumeric;
try {
  importStock('x,no,1');
} catch (error) {
  invalidNumeric = error.message;
}
assert.equal(invalidNumeric, 'invalid count');
const answer = {
  files: [
    { path: 'src/entry.js', symbol: 'importStock' },
    { path: 'src/input/csv.js', symbol: 'parseStock' },
    { path: 'src/domain/stock.js', symbol: 'normalizeStock' },
    { path: 'src/domain/sku.js', symbol: 'canonicalSku' },
    { path: 'src/output/wire.js', symbol: 'wireStock' }
  ],
  output: importStock(' ab-2 ,5,8'),
  invalid_numeric: invalidNumeric,
  reserved_applied_before_clamp: true
};
await writeFile('answer.json', JSON.stringify(answer, null, 2) + '\\n');
const saved = JSON.parse(await readFile('answer.json', 'utf8'));
assert.deepEqual(saved, answer);
assert.deepEqual(Object.keys(saved), ['files', 'output', 'invalid_numeric', 'reserved_applied_before_clamp']);
assert.deepEqual(saved.output, { product_code: 'AB-2', units: 0, schema: 2 });
process.stdout.write('answer.json written and verified\\n');
NODE"

